// QA joint for artwork (box 4.1): the WHOLE cross-module art contract walked
// over the REAL composed graph — a REAL cmd/mellifera server subprocess (the
// qaSerialStartServer harness: the production art.NewService wiring, the
// janitor's art task, the enrich queue + scan notify, and the
// ModulePresentation closure whose gate-resolved source_chain the poster walk
// consumes) running the REAL serial-scanner / serial-parser / frame-grabber /
// shikimori plugin subprocesses over a REAL store, with the shikimori
// upstream pinned to a local stub (MELLIFERA_SHIKIMORI_UPSTREAM — the poster
// URLs the plugin bakes carry the STUB origin, so the server's art fetches
// pull their bytes from the same stub; no test byte reaches the network).
//
// The flow (envelope order): a serial library scans and both series rows
// enrich, the stub serving ONE series a REAL poster and the OTHER the
// missing_original asset (the write-side drop: no poster key lands at all) →
// the grid document serves the first series' artwork THROUGH THE BINARY
// (/api/v1/art/object/art_<sha256>) once the janitor's settle materializes
// it, and omits the field for the placeholder series (honest absence) →
// GET /api/v1/art/object/{oid} answers through the REAL browse gate (a paired
// device token 200s with the exact bytes and the immutable cache headers; no
// token 401s) → PUT pins src:shikimori and the pin SURVIVES a whole-library
// metadata refresh that re-enriches to a NEW poster URL (the anchored by-id
// payload) → DELETE resets to the chain, idempotently (204 twice) → the
// art-task pass reclaims the orphaned sha-dir (GC on reference loss) while
// the new poster stands and serves.
package itest

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"image"
	"image/color"
	"image/jpeg"
	"io"
	"net/http"
	"net/http/httptest"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Fixture identity constants (no-coincidence discipline: independent of every
// other qa fixture's titles and ids) plus the art contract's local values.
// The trailing S01/S02 markers are the seasons the shared grammar cuts, so the
// derived search titles equal the clean names; the anime ids sit far from
// every other fixture's assignment.
const (
	qaArtDirA    = "QA Art Vault S01"
	qaArtEpARel  = qaArtDirA + "/QA Art Vault S01E01.mkv"
	qaArtDirB    = "QA Art Ridge S02"
	qaArtEpBRel  = qaArtDirB + "/QA Art Ridge S02E01.mkv"
	qaArtTitleA  = "QA Art Vault" // the season cut — parser title AND search key
	qaArtTitleB  = "QA Art Ridge" // ditto
	qaArtRussian = "Ку Арт"       // one RU pick shared by both candidates (never asserted on)
	qaArtIDa     = 5201           // row A's anime — the REAL poster
	qaArtIDb     = 5202           // row B's anime — the missing_original placeholder
	qaArtPlugin  = "shikimori"

	// The stub-side poster paths: A's search hit carries a REAL poster whose
	// bytes the stub serves; A's BY-ID payload (the anchored re-enrichment's
	// fetch shape) carries a DIFFERENT poster — the new URL that orphans the
	// first, no test-side flip needed. B's payloads always carry the known
	// missing-art asset, whose path prefix the shikimori write side drops
	// outright (artwork D9).
	qaArtPosterPathA  = "/images/animes/5201.jpg"
	qaArtPosterPathA2 = "/images/animes/5201-gen2.jpg"
	qaArtMissingPath  = "/assets/globals/missing_original.jpg"

	// qaArtInterval is the MELLIFERA_ART_INTERVAL knob value: the janitor's
	// art task (settle+GC) ticks this fast inside the REAL server, so the
	// materialization and the reclamation land in seconds without any test
	// side-channel into the subprocess.
	qaArtInterval = 250 * time.Millisecond

	// qaArtSettleTimeout bounds the waits on the janitor's passes (the tick
	// granularity is qaArtInterval; the margin is orders of magnitude).
	qaArtSettleTimeout = 30 * time.Second
)

// qaArtObjectPath is the served proxy-URL prefix the composition stamps for
// materialized artwork (the api's artObjectPath, re-derived on the black-box
// side).
const qaArtObjectPath = "/api/v1/art/object/"

// qaArtJPEG encodes a small real JPEG whose pixels carry seed — distinct
// seeds never share a content address, so the test can pre-compute the blob
// sha the server will store.
func qaArtJPEG(t *testing.T, seed byte) []byte {
	t.Helper()
	img := image.NewRGBA(image.Rect(0, 0, 30, 45)) // 2:3 portrait, poster-shaped
	for y := 0; y < 45; y++ {
		for x := 0; x < 30; x++ {
			img.Set(x, y, color.RGBA{R: seed, G: uint8(int(seed) + x), B: uint8(int(seed) + y), A: 255})
		}
	}
	var buf bytes.Buffer
	if err := jpeg.Encode(&buf, img, nil); err != nil {
		t.Fatalf("encode jpeg: %v", err)
	}
	return buf.Bytes()
}

// qaArtSHA is the content address of b (the blob dir name and the art token
// payload).
func qaArtSHA(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// qaArtAnime builds one upstream anime payload (the v1 shape Convert
// decodes; score is a decimal STRING upstream; posterPath is the image the
// plugin makes absolute against its api base — the STUB origin).
func qaArtAnime(id int, name, posterPath string) map[string]any {
	return map[string]any{
		"id": id, "name": name, "russian": qaArtRussian, "kind": "tv", "status": "released",
		"score": "7.6", "episodes": 12, "aired_on": "2021-04-04",
		"description": "qa art stub " + name,
		"url":         "/api/animes/" + strconv.Itoa(id) + "-qa",
		"image":       map[string]any{"original": posterPath},
		"genre": []any{
			map[string]any{"name": "Action", "russian": "Экшен"},
		},
	}
}

// qaArtStub is the fake shikimori origin: the search lists carry A's REAL
// poster path and B's missing_original path; the BY-ID payloads (what the
// anchored re-enrichment fetches) carry A's SECOND poster path; the poster
// bytes themselves are served beside the API payloads.
type qaArtStub struct {
	base string
}

func qaArtStartStub(t *testing.T, poster1, poster2 []byte) *qaArtStub {
	t.Helper()
	mux := http.NewServeMux()
	searchList := map[string][]map[string]any{
		qaArtTitleA: {qaArtAnime(qaArtIDa, qaArtTitleA, qaArtPosterPathA)},
		qaArtTitleB: {qaArtAnime(qaArtIDb, qaArtTitleB, qaArtMissingPath)},
	}
	mux.HandleFunc("/api/animes", func(w http.ResponseWriter, r *http.Request) {
		list, ok := searchList[r.URL.Query().Get("search")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, list)
	})
	byID := map[string]map[string]any{
		strconv.Itoa(qaArtIDa): qaArtAnime(qaArtIDa, qaArtTitleA, qaArtPosterPathA2),
		strconv.Itoa(qaArtIDb): qaArtAnime(qaArtIDb, qaArtTitleB, qaArtMissingPath),
	}
	mux.HandleFunc("/api/animes/", func(w http.ResponseWriter, r *http.Request) {
		// The by-id companions (/roles, /episodes) miss the map and 404 —
		// the tolerated shape every sibling joint's stub serves.
		e, ok := byID[strings.TrimPrefix(r.URL.Path, "/api/animes/")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		qaSerialWriteJSON(t, w, e)
	})
	blobs := map[string][]byte{
		qaArtPosterPathA:  poster1,
		qaArtPosterPathA2: poster2,
	}
	mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
		body, ok := blobs[r.URL.Path]
		if !ok {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("Content-Type", "image/jpeg")
		_, _ = w.Write(body)
	})
	hs := httptest.NewServer(mux)
	t.Cleanup(hs.Close)
	return &qaArtStub{base: hs.URL}
}

// qaArtWriteFixtures writes the serial library root: two series directories,
// one episode each (the probeable-minimum the real scanner chain needs).
func qaArtWriteFixtures(t *testing.T, root string) {
	t.Helper()
	qaSerialMedia(t, filepath.Join(root, qaArtEpARel))
	qaSerialMedia(t, filepath.Join(root, qaArtEpBRel))
}

// qaArtJoint is one composed artwork joint: the real server subprocess, the
// stub upstream, and the serial library under contract.
type qaArtJoint struct {
	srv     qaSerialServer
	client  *http.Client
	token   string
	artRoot string // the server's content-addressed blob tree (dataDir/art)
	lib     int64
}

// qaArtStartJoint boots the joint: the REAL cmd/mellifera subprocess (its
// main.go wiring carries art.NewService, the janitor's art task at
// MELLIFERA_ART_INTERVAL, the enrich queue + scan notify, and the production
// ModulePresentation closure), the seven plugin binaries, and the stub
// upstream pinned through the env seam. The scan stays with the caller.
func qaArtStartJoint(t *testing.T, up *qaArtStub, root string) *qaArtJoint {
	t.Helper()
	for _, bin := range []string{"ffmpeg", "ffprobe"} {
		if _, err := exec.LookPath(bin); err != nil {
			t.Skipf("artwork joint needs %s on PATH (fixtures are lavfi-generated): %v", bin, err)
		}
	}
	// The janitor's art-task cadence, inherited by the subprocess at boot
	// (t.Setenv restores it; no test in this package runs parallel).
	t.Setenv("MELLIFERA_ART_INTERVAL", qaArtInterval.String())
	tmp := t.TempDir()
	srv := qaSerialStartServer(t, qaSerialServerBins{
		server:        buildBinary(t, tmp, "qa-art-server", "./cmd/mellifera"),
		baseScanner:   buildBinary(t, tmp, "qa-art-basescanner", "./plugins/base-scanner"),
		tvParser:      buildBinary(t, tmp, "qa-art-tvparser", "./plugins/tv-parser"),
		imageEnricher: buildBinary(t, tmp, "qa-art-imageenricher", "./plugins/image-enricher"),
		serialScanner: buildBinary(t, tmp, "qa-art-scanner", "./plugins/serial-scanner"),
		serialParser:  buildBinary(t, tmp, "qa-art-parser", "./plugins/serial-parser"),
		frameGrabber:  buildBinary(t, tmp, "qa-art-grabber", "./plugins/frame-grabber"),
	}, up.base, tmp, "qa-art-admin-token")
	j := &qaArtJoint{
		srv:     srv,
		client:  &http.Client{Timeout: httpTimeout},
		token:   "qa-art-admin-token",
		artRoot: filepath.Join(srv.dataDir, "art"),
	}
	j.lib = qaSerialCreateLibrary(t, j.client, j.srv.baseURL, j.token, root, "QA Artwork")
	return j
}

// qaArtSeriesRow is the QA-local decode of the series wire shape's
// art-relevant fields. Artwork is a POINTER so the decode distinguishes the
// key's absence (nil — the honest-absence contract, the omitempty omitting)
// from any value it might carry.
type qaArtSeriesRow struct {
	ID           string          `json:"id"`
	RelativePath string          `json:"relative_path"`
	Status       string          `json:"status"`
	Artwork      *string         `json:"artwork"`
	Document     json.RawMessage `json:"document"`
}

// qaArtGrid decodes a library's series list rows with presence-faithful
// artwork.
func qaArtGrid(t *testing.T, j *qaArtJoint) []qaArtSeriesRow {
	t.Helper()
	var resp struct {
		Items []qaArtSeriesRow `json:"items"`
	}
	url := j.srv.baseURL + "/api/v1/series?library=" + strconv.FormatInt(j.lib, 10)
	if status := doRequest(t, j.client, http.MethodGet, url, j.token, nil, &resp); status != http.StatusOK {
		t.Fatalf("list series lib %d: HTTP %d, want 200", j.lib, status)
	}
	return resp.Items
}

// qaArtRowByPath returns one grid row by relative path (fatal when missing).
func qaArtRowByPath(t *testing.T, rows []qaArtSeriesRow, rel string) qaArtSeriesRow {
	t.Helper()
	for _, sr := range rows {
		if sr.RelativePath == rel {
			return sr
		}
	}
	t.Fatalf("series %q missing from the grid", rel)
	return qaArtSeriesRow{}
}

// qaArtDocShikimori decodes a stored document's shikimori namespace poster
// fact: landed reports whether the namespace exists at all; poster is its
// stored poster URL ("" = no poster key — the write-side drop's shape).
func qaArtDocShikimori(t *testing.T, raw json.RawMessage) (landed bool, poster string) {
	t.Helper()
	var doc struct {
		Sources map[string]struct {
			Poster string `json:"poster"`
		} `json:"sources"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatalf("decode document: %v", err)
	}
	_, landed = doc.Sources["shikimori"]
	return landed, doc.Sources["shikimori"].Poster
}

// qaArtAwaitPoster polls the grid until the row at rel is ready with its
// shikimori namespace landed and the given poster fact stored (wantPoster ""
// demands the namespace WITH NO poster key — the placeholder's honest
// shape), returning the settled row.
func qaArtAwaitPoster(t *testing.T, j *qaArtJoint, rel, wantPoster string) qaArtSeriesRow {
	t.Helper()
	deadline := time.Now().Add(qaSerialDrainTimeout)
	for time.Now().Before(deadline) {
		for _, sr := range qaArtGrid(t, j) {
			if sr.RelativePath != rel || sr.Status != "ready" {
				continue
			}
			landed, poster := qaArtDocShikimori(t, sr.Document)
			if landed && poster == wantPoster {
				return sr
			}
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("series %q: namespace with poster %q never landed within %s", rel, wantPoster, qaSerialDrainTimeout)
	return qaArtSeriesRow{}
}

// qaArtAwaitArtwork polls the grid until the row at rel carries EXACTLY the
// wanted artwork value (presence required — nil never passes).
func qaArtAwaitArtwork(t *testing.T, j *qaArtJoint, rel, want string) qaArtSeriesRow {
	t.Helper()
	deadline := time.Now().Add(qaArtSettleTimeout)
	for time.Now().Before(deadline) {
		sr := qaArtRowByPath(t, qaArtGrid(t, j), rel)
		if sr.Artwork != nil && *sr.Artwork == want {
			return sr
		}
		time.Sleep(probeInterval)
	}
	sr := qaArtRowByPath(t, qaArtGrid(t, j), rel)
	got := "<absent>"
	if sr.Artwork != nil {
		got = *sr.Artwork
	}
	t.Fatalf("series %q: artwork %q never became %q within %s", rel, got, want, qaArtSettleTimeout)
	return qaArtSeriesRow{}
}

// qaArtAwaitBlob polls the server's blob tree until the sha dir's existence
// matches want — the materialization (true) and the GC reclamation (false)
// observed on the REAL filesystem the janitor's passes write.
func qaArtAwaitBlob(t *testing.T, j *qaArtJoint, sha string, want bool) {
	t.Helper()
	dir := filepath.Join(j.artRoot, sha)
	deadline := time.Now().Add(qaArtSettleTimeout)
	for time.Now().Before(deadline) {
		_, err := os.Stat(dir)
		if want == (err == nil) {
			return
		}
		time.Sleep(probeInterval)
	}
	t.Fatalf("blob dir %s existence = !%v within %s", dir, want, qaArtSettleTimeout)
}

// qaArtGetBytes performs one raw GET, returning status, headers, and body —
// the byte-and-header assertions JSON decoding would swallow.
func qaArtGetBytes(t *testing.T, c *http.Client, url, token string) (int, http.Header, []byte) {
	t.Helper()
	req, err := http.NewRequest(http.MethodGet, url, nil)
	if err != nil {
		t.Fatalf("new request %s: %v", url, err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("get %s: %v", url, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read %s: %v", url, err)
	}
	return resp.StatusCode, resp.Header, body
}

// qaArtPosters fetches one series' poster-candidates envelope.
func qaArtPosters(t *testing.T, j *qaArtJoint, seriesID string) (current string, candidates []map[string]any) {
	t.Helper()
	var resp struct {
		Current    string           `json:"current"`
		Candidates []map[string]any `json:"candidates"`
	}
	url := j.srv.baseURL + "/api/v1/series/" + seriesID + "/posters"
	if status := doRequest(t, j.client, http.MethodGet, url, j.token, nil, &resp); status != http.StatusOK {
		t.Fatalf("GET posters of %s: HTTP %d, want 200", seriesID, status)
	}
	return resp.Current, resp.Candidates
}

// TestArtworkJointFlow is the Tier-1 joint round trip of the artwork
// contract: scan → shikimori-enrich (real poster vs missing_original) →
// composition on the grid (proxy URL vs honest absence) → the art object
// route behind the browse gate → pin / refresh survival / reset / GC.
func TestArtworkJointFlow(t *testing.T) {
	if testing.Short() {
		t.Skip("artwork joint: skips under -short (builds binaries + subprocesses)")
	}
	poster1 := qaArtJPEG(t, 0xA1)
	poster2 := qaArtJPEG(t, 0xB2)
	sha1, sha2 := qaArtSHA(poster1), qaArtSHA(poster2)

	fixtureRoot := t.TempDir()
	qaArtWriteFixtures(t, fixtureRoot)
	up := qaArtStartStub(t, poster1, poster2)
	j := qaArtStartJoint(t, up, fixtureRoot)

	// --- leg 1: the REAL scan drains both series rows ---
	res := scanLibrary(t, j.client, j.srv.baseURL, j.token, j.lib)
	if res.Persisted < 2 {
		t.Fatalf("scan persisted = %d, want >= 2 (both series fixtures)", res.Persisted)
	}

	// --- leg 2: the enrichment lands EXACTLY the two poster shapes ---
	// A: the REAL poster URL (the stub origin the plugin bakes); B: the
	// namespace WITHOUT a poster key — the missing_original asset the write
	// side dropped (D9).
	qaArtAwaitPoster(t, j, qaArtDirA, up.base+qaArtPosterPathA)
	qaArtAwaitPoster(t, j, qaArtDirB, "")

	// --- leg 3: the grid composes — proxy URL through the binary vs absence ---
	// The janitor's settle materializes A's poster; the grid read then stamps
	// the SERVED proxy URL. B's row omits the field entirely (honest absence:
	// the walk found no usable poster and there is nothing to show).
	srA := qaArtAwaitArtwork(t, j, qaArtDirA, qaArtObjectPath+"art_"+sha1)
	if rowB := qaArtRowByPath(t, qaArtGrid(t, j), qaArtDirB); rowB.Artwork != nil {
		t.Fatalf("placeholder series artwork = %v, want the key ABSENT (honest absence, never a placeholder URL)", *rowB.Artwork)
	}

	// --- leg 4: the art object route behind the REAL browse gate ---
	// A paired device (the REAL pairing flow: mint → approve → pickup) reads
	// the bytes 200 with the immutable cache headers; an anonymous call 401s.
	var created map[string]any
	if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/pair", "", nil, &created); status != http.StatusOK {
		t.Fatalf("POST /pair: HTTP %d, want 200", status)
	}
	pairingID, _ := created["pairing_id"].(string)
	if pairingID == "" {
		t.Fatalf("POST /pair body = %v, want a pairing_id", created)
	}
	if status := doRequest(t, j.client, http.MethodPost, j.srv.baseURL+"/api/v1/admin/pairings/"+pairingID+"/approve", j.token, nil, nil); status != http.StatusOK {
		t.Fatalf("approve: HTTP %d, want 200", status)
	}
	var pickup map[string]any
	if status := doRequest(t, j.client, http.MethodGet, j.srv.baseURL+"/api/v1/pair/"+pairingID+"/wait", "", nil, &pickup); status != http.StatusOK {
		t.Fatalf("wait: HTTP %d, want 200", status)
	}
	deviceToken, _ := pickup["device_token"].(string)
	if deviceToken == "" {
		t.Fatalf("wait body = %v, want a device_token", pickup)
	}
	url1 := j.srv.baseURL + qaArtObjectPath + "art_" + sha1
	status, header, body := qaArtGetBytes(t, j.client, url1, deviceToken)
	if status != http.StatusOK {
		t.Fatalf("device GET art object: HTTP %d, want 200 (RoleClient through the browse group)", status)
	}
	if !bytes.Equal(body, poster1) {
		t.Fatalf("art object body = %d bytes, want the exact %d poster bytes", len(body), len(poster1))
	}
	if got := header.Get("Cache-Control"); got != "private, immutable" {
		t.Fatalf("Cache-Control = %q, want private, immutable (write-once bytes)", got)
	}
	if got := header.Get("ETag"); got != `"`+sha1+`"` {
		t.Fatalf("ETag = %q, want the content address %q", got, `"`+sha1+`"`)
	}
	if got := header.Get("Content-Type"); !strings.HasPrefix(got, "image/jpeg") {
		t.Fatalf("Content-Type = %q, want image/jpeg", got)
	}
	if anonStatus, _, _ := qaArtGetBytes(t, j.client, url1, ""); anonStatus != http.StatusUnauthorized {
		t.Fatalf("anonymous GET art object: HTTP %d, want 401 (the browse gate)", anonStatus)
	}

	// --- leg 5: PUT pins the chain source; the record is the stored form ---
	var pinned struct {
		EntityID   string `json:"entity_id"`
		EntityKind string `json:"entity_kind"`
		Selection  string `json:"selection"`
		UpdatedAt  string `json:"updated_at"`
	}
	putURL := j.srv.baseURL + "/api/v1/series/" + srA.ID + "/poster"
	if status := doRequest(t, j.client, http.MethodPut, putURL, j.token, map[string]string{"selection": "src:shikimori"}, &pinned); status != http.StatusOK {
		t.Fatalf("PUT poster: HTTP %d, want 200", status)
	}
	if pinned.EntityID != srA.ID || pinned.EntityKind != "series" || pinned.Selection != "src:shikimori" || pinned.UpdatedAt == "" {
		t.Fatalf("PUT record = %+v, want {entity_id %s, series, src:shikimori, a stamp}", pinned, srA.ID)
	}
	current, candidates := qaArtPosters(t, j, srA.ID)
	if current != "src:shikimori" {
		t.Fatalf("posters current = %q, want src:shikimori", current)
	}
	foundSrc := false
	for _, c := range candidates {
		if c["source"] == "shikimori" {
			foundSrc = true
		}
	}
	if !foundSrc {
		t.Fatalf("posters candidates = %v, want a shikimori-source candidate", candidates)
	}

	// --- leg 6: the pin SURVIVES a whole-library metadata refresh that
	// re-enriches to a NEW poster URL ---
	// POST refresh sweeps both rows: the strip clears each namespace and the
	// drain re-fetches ANCHORED (identifiers.shikimori_id → the stub's
	// by-id payload), which carries A's SECOND poster path. The override row
	// is control state beside the document — refresh never touches it.
	if status := doRequest(t, j.client, http.MethodPost,
		fmt.Sprintf("%s/api/v1/libraries/%d/refresh", j.srv.baseURL, j.lib),
		j.token, map[string]string{"plugin_id": qaArtPlugin}, nil); status != http.StatusAccepted {
		t.Fatalf("POST refresh: HTTP %d, want 202", status)
	}
	qaArtAwaitPoster(t, j, qaArtDirA, up.base+qaArtPosterPathA2)
	current, _ = qaArtPosters(t, j, srA.ID)
	if current != "src:shikimori" {
		t.Fatalf("posters current after refresh = %q, want src:shikimori (the pin survives a metadata refresh)", current)
	}

	// --- leg 7: DELETE resets to the chain, idempotently ---
	if status := doRequest(t, j.client, http.MethodDelete, putURL, j.token, nil, nil); status != http.StatusNoContent {
		t.Fatalf("DELETE poster: HTTP %d, want 204", status)
	}
	if status := doRequest(t, j.client, http.MethodDelete, putURL, j.token, nil, nil); status != http.StatusNoContent {
		t.Fatalf("DELETE poster (repeat): HTTP %d, want 204 (idempotent)", status)
	}
	current, _ = qaArtPosters(t, j, srA.ID)
	if current != "" {
		t.Fatalf("posters current after reset = %q, want empty (the chain composes)", current)
	}

	// --- leg 8: the art-task pass settles the NEW poster and the GC
	// reclaims the ORPHANED sha-dir on reference loss ---
	// The refresh moved A's live reference to poster2, so poster1's fetch
	// row lost its last reference: the janitor's next pass (the REAL
	// MELLIFERA_ART_INTERVAL tick in the subprocess) acquires the new URL
	// into its own blob dir and deletes the orphaned row together with its
	// sha-dir.
	qaArtAwaitBlob(t, j, sha2, true)
	qaArtAwaitBlob(t, j, sha1, false)
	// The composition follows the reclaim: A now composes the CHAIN winner —
	// poster2, staged — through the binary; B still omits; and the new
	// winner serves through the same browse gate.
	qaArtAwaitArtwork(t, j, qaArtDirA, qaArtObjectPath+"art_"+sha2)
	if rowB := qaArtRowByPath(t, qaArtGrid(t, j), qaArtDirB); rowB.Artwork != nil {
		t.Fatalf("placeholder series artwork after refresh = %v, want the key ABSENT", *rowB.Artwork)
	}
	status2, _, body2 := qaArtGetBytes(t, j.client, j.srv.baseURL+qaArtObjectPath+"art_"+sha2, deviceToken)
	if status2 != http.StatusOK || !bytes.Equal(body2, poster2) {
		t.Fatalf("new winner art object: HTTP %d %d bytes, want 200 and the exact %d bytes", status2, len(body2), len(poster2))
	}

	// --- advisory observation (the wf-coder handoff flag, NOT a contract
	// assert): the thumb candidate's served URL shape. The episode item
	// carries the real frame-grabber fact once the chain's grabber stage
	// lands; the server composes its thumb candidate url WITHOUT the
	// /api/v1 prefix (itemThumbPath), while the SPA's overlay renders thumb
	// cards via ENDPOINTS.itemMedia. Logged for the GATE 2 reviewer to
	// adjudicate; deliberately not fixed here.
	if epID, ok := qaArtFirstEpisode(t, j, srA.ID); ok {
		var itemPosters struct {
			Current    string           `json:"current"`
			Candidates []map[string]any `json:"candidates"`
		}
		if status := doRequest(t, j.client, http.MethodGet,
			j.srv.baseURL+"/api/v1/items/"+epID+"/posters", j.token, nil, &itemPosters); status == http.StatusOK {
			for _, c := range itemPosters.Candidates {
				if c["source"] == "thumb" {
					t.Logf("QA OBSERVATION (handoff flag): thumb candidate url = %q (no /api/v1 prefix; the SPA rides ENDPOINTS.itemMedia instead)", c["url"])
				}
			}
		}
	}
}

// qaArtFirstEpisode returns one series' first episode item id (ok=false when
// none is listed — the observation leg is advisory and skips cleanly).
func qaArtFirstEpisode(t *testing.T, j *qaArtJoint, seriesID string) (string, bool) {
	t.Helper()
	var resp struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
	}
	url := j.srv.baseURL + "/api/v1/series/" + seriesID + "/episodes"
	if status := doRequest(t, j.client, http.MethodGet, url, j.token, nil, &resp); status != http.StatusOK {
		return "", false
	}
	if len(resp.Items) == 0 {
		return "", false
	}
	return resp.Items[0].ID, true
}
